wxSizer *s_dlgcnt;
wxSizer *contentSizer;
wxSizer *s_fed2klh;
wxSizer *muleDlg( wxWindow *parent, bool call_fit, bool set_sizer )
{
    wxBoxSizer *item0 = new wxBoxSizer( wxVERTICAL );
    s_dlgcnt = item0;

    wxBoxSizer *item1 = new wxBoxSizer( wxVERTICAL );
    contentSizer = item1;

    item0->Add( item1, wxSizerFlags(1).Expand().CenterVertical() );
    wxFlexGridSizer *item2 = new wxFlexGridSizer( 2, 0, 0 );
    item2->AddGrowableCol( 0 );
    s_fed2klh = item2;

    // The old "eD2k Link:" label is gone -- the text control's placeholder
    // ("Paste eD2k or magnet links here") now conveys the same thing.
    CMuleTextCtrl *item4 = new CMuleTextCtrl( parent, -1, "", wxDefaultPosition, wxDefaultSize, wxTE_MULTILINE );
    item4->SetName( "FastEd2kLinks" );
    item4->SetPlaceholder( _("Paste eD2k or magnet links here") );
    item2->Add( item4, wxSizerFlags(1).Expand().Border(wxALL, 5) );
    wxButton *item5 = new wxButton( parent, ID_BUTTON_FAST, _("Add links"), wxDefaultPosition, wxDefaultSize, 0 );
    item5->SetToolTip( _("Click here to add the eD2k link in the text control to your download queue.") );
    item2->Add( item5, wxSizerFlags().Center().Border(wxRIGHT, 5) );
    item0->Add( item2, wxSizerFlags().Expand().CenterVertical() );
    wxBoxSizer *item6 = new wxBoxSizer( wxHORIZONTAL );

    wxStaticBitmap *item7 = new wxStaticBitmap( parent, -1, wxArtProvider::GetBitmapBundle( "amule:status_log_info" ), wxDefaultPosition, wxDefaultSize );
    item7->SetToolTip( _("Events are displayed here. For a complete list of events, refer to the log in the Servers-tab.") );
    item6->Add( item7, wxSizerFlags().Center() );

    wxStaticText *item8 = new wxStaticText( parent, -1, _("Loading ..."), wxDefaultPosition, wxSize(140,-1), wxST_NO_AUTORESIZE );
    item8->SetName( "infoLabel" );
    item6->Add( item8, wxSizerFlags(1).FixedMinSize().Center().Border(wxLEFT, 5) );
    wxStaticLine *item9 = new wxStaticLine( parent, -1, wxDefaultPosition, wxSize(-1,20), wxLI_VERTICAL );
    item6->Add( item9, wxSizerFlags().Center().Border(wxLEFT, 5) );

    wxStaticBitmap *item10 = new wxStaticBitmap( parent, -1, wxArtProvider::GetBitmapBundle( "amule:status_users" ), wxDefaultPosition, wxDefaultSize );
    item10->SetToolTip( _("Number of users on the server you are connected to ...") );
    item6->Add( item10, wxSizerFlags().Center().Border(wxLEFT|wxRIGHT, 5) );

    wxStaticText *item11 = new wxStaticText( parent, -1, _("Users: 0"), wxDefaultPosition, wxDefaultSize, 0 );
    item11->SetToolTip( _("Users connected to the current server and an estimate of the total number of users.") );
    item11->SetName( "userLabel" );
    item6->Add( item11, wxSizerFlags().Center().Border(wxLEFT|wxRIGHT, 5) );
    wxStaticLine *item12 = new wxStaticLine( parent, -1, wxDefaultPosition, wxSize(-1,20), wxLI_VERTICAL );
    item6->Add( item12, wxSizerFlags().Center().Border(wxLEFT, 5) );
    wxStaticBitmap *item13 = new wxStaticBitmap( parent, -1, wxArtProvider::GetBitmapBundle( "amule:status_speed_idle" ), wxDefaultPosition, wxDefaultSize );
    item13->SetName( "transferImg" );
    item6->Add( item13, wxSizerFlags().Center().Border(wxLEFT|wxRIGHT, 5) );
    wxStaticText *item14 = new wxStaticText( parent, -1, _("Up: 0.0 | Down: 0.0"), wxDefaultPosition, wxDefaultSize, 0 );
    item14->SetToolTip( _("Current average upload and download rates. If enabled the numbers in the braces signify the overhead from client communication.") );
    item14->SetName( "speedLabel" );
    item6->Add( item14, wxSizerFlags().Center().Border(wxLEFT|wxRIGHT, 5) );

    wxStaticLine *item15 = new wxStaticLine( parent, -1, wxDefaultPosition, wxSize(-1,20), wxLI_VERTICAL );
    item6->Add( item15, wxSizerFlags().Center().Border(wxLEFT, 5) );
    wxStaticBitmap *item16 = new wxStaticBitmap( parent, -1, wxArtProvider::GetBitmapBundle( "amule:status_conn_base" ), wxDefaultPosition, wxDefaultSize );
    item16->SetToolTip( _("Displays the connected status and active transfers. Red arrows signifies that you are currently not connected, yellow arrows signify that you have low ID (firewalled) and green arrows signify that you have high ID (The optimal connection type).") );
    item16->SetName( "connImage" );
    item6->Add( item16, wxSizerFlags().Center().Border(wxLEFT|wxRIGHT, 5) );
    wxStaticText *item17 = new wxStaticText( parent, -1, _("Not Connected ..."), wxDefaultPosition, wxDefaultSize, 0 );
    item17->SetToolTip( _("Currently connected server.") );
    item17->SetName( "connLabel" );
    item6->Add( item17, wxSizerFlags().Center().Border(wxRIGHT, 5) );
#if defined(__WXMAC__)
    // macOS rounds the frame's bottom corners, clipping content that sits flush
    // against the edge. Inset the status row -- a wider left margin for the
    // leading icon, a slimmer bottom margin -- so nothing is cut off.
    item6->PrependSpacer(16);
    item0->Add( item6, wxSizerFlags().Expand().CenterVertical().Border(wxRIGHT|wxBOTTOM, 6) );
#else
    item0->Add( item6, wxSizerFlags().Expand().CenterVertical().Border(wxLEFT, 5) );
#endif
    if (set_sizer)
    {
        parent->SetSizer( item0 );
        if (call_fit)
            item0->SetSizeHints( parent );
    }
    
    return item0;
}

wxSizer *serverListDlg( wxWindow *parent, bool call_fit, bool set_sizer )
{
    wxBoxSizer *item0 = new wxBoxSizer( wxVERTICAL );

    wxSplitterWindow *item1 = new wxSplitterWindow( parent, ID_SRV_SPLITTER, wxDefaultPosition, wxDefaultSize, wxSP_LIVE_UPDATE );
    wxPanel *item2 = new wxPanel( item1, -1 );
    NetDialog( item2, FALSE, TRUE );
    wxPanel *item3 = new wxPanel( item1, -1 );
    serverListDlgDown( item3, FALSE, TRUE );
    item1->SplitHorizontally( item2, item3 );
    item1->SetName( "SrvSplitterWnd" );
    item0->Add( item1, wxSizerFlags(1).Expand().CenterVertical() );
    if (set_sizer)
    {
        parent->SetSizer( item0 );
        if (call_fit)
            item0->SetSizeHints( parent );
    }
    
    return item0;
}

