wxSizer *transferTopPane( wxWindow *parent, bool call_fit, bool set_sizer )
{
    wxBoxSizer *item0 = new wxBoxSizer( wxVERTICAL );

    wxBoxSizer *item1 = new wxBoxSizer( wxHORIZONTAL );

    wxBitmapButton *item2 = new wxBitmapButton( parent, ID_BTNCLRCOMPL, wxArtProvider::GetBitmapBundle( "amule:transfer_clear_completed" ), wxDefaultPosition, wxSize(34,34) );
    item2->SetToolTip( _("Clears completed downloads") );
    item2->Enable( false );
    item1->Add( item2, wxSizerFlags().Center().FixedMinSize().Border(wxLEFT|wxRIGHT, 5) );
    wxStaticText *item3 = new wxStaticText( parent, -1, _("Downloads"), wxDefaultPosition, wxDefaultSize, 0 );
    item3->SetName( "downloadsLabel" );
    item1->Add( item3, wxSizerFlags().Center().Border(wxLEFT|wxRIGHT, 5) );
    CMuleNotebook *item4 = new CMuleNotebook( parent, ID_CATEGORIES, wxDefaultPosition, wxSize(15,MULE_NOTEBOOK_TAB_HEIGHT), 0 );
    wxASSERT( item4 );
    item1->Add( item4, wxSizerFlags(1).FixedMinSize().Center() );
    wxStaticText *itemDlFilterLabel = new wxStaticText( parent, -1, _("Filter:"), wxDefaultPosition, wxDefaultSize, 0 );
    item1->Add( itemDlFilterLabel, wxSizerFlags().Center().Border(wxLEFT, 5) );
    wxTextCtrl *itemDlFilter = new wxTextCtrl( parent, IDC_TRANSFER_FILTER, "", wxDefaultPosition, wxSize(150,-1), 0 );
    item1->Add( itemDlFilter, wxSizerFlags().Center().Border(wxLEFT|wxRIGHT, 5) );
    item0->Add( item1, wxSizerFlags().Expand().CenterVertical() );
    CDownloadListCtrl *item5 = new CDownloadListCtrl( parent, ID_DLOADLIST, wxDefaultPosition, wxDefaultSize, wxLC_REPORT|wxSUNKEN_BORDER );
    item5->SetName( "downloadList" );
    item0->Add( item5, wxSizerFlags(1).Expand().CenterVertical() );
    if (set_sizer)
    {
        parent->SetSizer( item0 );
        if (call_fit)
            item0->SetSizeHints( parent );
    }
    
    return item0;
}

wxSizer *s_clientlistHeader;
wxSizer *transferBottomPane( wxWindow *parent, bool call_fit, bool set_sizer )
{
    wxFlexGridSizer *item0 = new wxFlexGridSizer( 2, 0, 0, 0 );
    item0->AddGrowableCol( 0 );
    item0->AddGrowableRow( 1 );

    wxFlexGridSizer *item1 = new wxFlexGridSizer( 3, 0, 1 );
    item1->AddGrowableCol( 1 );
    s_clientlistHeader = item1;

    wxBitmapButton *item2 = new wxBitmapButton( parent, ID_CLIENTTOGGLE, wxArtProvider::GetBitmapBundle( "amule:arrows_down" ), wxDefaultPosition, wxDefaultSize );
    item1->Add( item2, wxSizerFlags().CenterVertical() );

    wxBoxSizer *item3 = new wxBoxSizer( wxHORIZONTAL );

    wxStaticText *item4 = new wxStaticText( parent, -1, _("File sources:"), wxDefaultPosition, wxDefaultSize, 0 );
    item3->Add( item4, wxSizerFlags().Center() );

    wxStaticText *item5 = new wxStaticText( parent, ID_CLIENTCOUNT, "0", wxDefaultPosition, wxDefaultSize, wxST_NO_AUTORESIZE );
    item5->SetForegroundColour( wxSystemSettings::GetColour(wxSYS_COLOUR_HOTLIGHT) );
    item3->Add( item5, wxSizerFlags().CenterVertical().Border(wxLEFT|wxRIGHT, 5) );
    item1->Add( item3, wxSizerFlags().Center().Border(wxLEFT|wxRIGHT, 5) );

    // Combined size of the downloads currently visible (category + text
    // filter), right-aligned in the growable header's third column. Set by
    // CDownloadListCtrl::SetTotalSize(). No wxST_NO_AUTORESIZE: the label must
    // grow to fit its text (it starts empty, so the flag would pin it 0-wide).
    wxStaticText *item5b = new wxStaticText( parent, -1, wxEmptyString, wxDefaultPosition, wxDefaultSize, wxALIGN_RIGHT );
    item5b->SetName( "downloadsTotalSize" );
    item1->Add( item5b, wxSizerFlags().CenterVertical().Border(wxLEFT|wxRIGHT, 5) );

    item0->Add( item1, wxSizerFlags().Expand().CenterVertical() );
    CSourceListCtrl *item6 = new CSourceListCtrl( parent, ID_CLIENTLIST, wxDefaultPosition, wxDefaultSize, wxLC_REPORT|wxSUNKEN_BORDER );
    item0->Add( item6, wxSizerFlags(1).Expand() );

    if (set_sizer)
    {
        parent->SetSizer( item0 );
        if (call_fit)
            item0->SetSizeHints( parent );
    }
    
    return item0;
}

wxSizer *messagePage( wxWindow *parent, bool call_fit, bool set_sizer )
{
    wxStaticBox *item1 = new wxStaticBox( parent, -1, "" );
    wxStaticBoxSizer *item0 = new wxStaticBoxSizer( item1, wxVERTICAL );

    wxSplitterWindow *item2 = new wxSplitterWindow( parent, ID_MESSAGESPLATTER, wxDefaultPosition, wxDefaultSize, wxSP_LIVE_UPDATE );
    item2->SetMinimumPaneSize( 20 );
    wxPanel *item3 = new wxPanel( item2, -1 );
    messagePageFriends( item3, FALSE, TRUE );
    wxPanel *item4 = new wxPanel( item2, -1 );
    messagePageMessages( item4, FALSE, TRUE );
    item2->SplitVertically( item3, item4 );
    item0->Add( item2, wxSizerFlags(1).Expand().CenterVertical() );
    if (set_sizer)
    {
        parent->SetSizer( item0 );
        if (call_fit)
            item0->SetSizeHints( parent );
    }
    
    return item0;
}

namespace
{
// File-details helper: append a "label" + HOTLIGHT-coloured value pair (the
// value control carrying `valueId`, initialised to "N/A") to `grid` as one
// horizontal row. Mirrors the label/value styling used throughout
// fileDetails(), so the relocated download rows and the Sharing box stay
// visually consistent with the hand-written rows.
//
// `appendColon` tacks a literal " :" onto the label at display time. The
// Sharing rows use it so they can reuse existing bare translations (e.g.
// "Requests") and still read "Requests :" without minting new catalog strings.
void AddFileDetailRow(
    wxWindow *rowParent, wxSizer *grid, const wxString &label, int valueId, bool appendColon = false )
{
    wxBoxSizer *row = new wxBoxSizer( wxHORIZONTAL );
    row->Add( new wxStaticText( rowParent, -1, appendColon ? label + wxT(" :") : label,
                  wxDefaultPosition, wxDefaultSize, 0 ),
        wxSizerFlags().Expand().CenterVertical() );
    wxStaticText *val = new wxStaticText( rowParent, valueId, _("N/A"), wxDefaultPosition, wxDefaultSize, 0 );
    val->SetForegroundColour( wxSystemSettings::GetColour(wxSYS_COLOUR_HOTLIGHT) );
    row->Add( val, wxSizerFlags().Center().Border(wxLEFT, 5) );
    grid->Add( row, wxSizerFlags().Expand().CenterVertical() );
}
} // namespace

